import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"Workflows — develop at scale","description":"","frontmatter":{"title":"Workflows — develop at scale","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"Workflows — develop at scale | Millennium Solutions"}],["meta",{"property":"og:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/WORKFLOWS.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Workflows — develop at scale | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"ℤ/9 vortex framework — recomputable proof of concept"}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/WORKFLOWS.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/WORKFLOWS.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/WORKFLOWS.html"}]]},"headers":[],"relativePath":"WORKFLOWS.md","filePath":"WORKFLOWS.md"}`),a={name:`WORKFLOWS.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="workflows-—-developing-uuidna-at-scale" tabindex="-1">Workflows — developing uuidna at scale <a class="header-anchor" href="#workflows-—-developing-uuidna-at-scale" aria-label="Permalink to “Workflows — developing uuidna at scale”">​</a></h1><p>The repeatable, gated procedures for growing the deposit. Each is a command or a checked sequence; nothing is asserted, every step recomputes. Earned, not minted.</p><h2 id="the-wave-—-add-theorems" tabindex="-1">The wave — add theorems <a class="header-anchor" href="#the-wave-—-add-theorems" aria-label="Permalink to “The wave — add theorems”">​</a></h2><ol><li><strong>Draft</strong> candidates as <code>test: () =&gt; boolean</code> in <code>scripts/discover.ts</code> — decidable, exhaustive over a finite domain (a fact that <em>computes</em>, never a claim).</li><li><strong>Verify green first</strong> — before inserting, each candidate must: its <code>test()</code> returns <code>true</code>, its name passes the honesty gate (<code>computes(name).binary === 1</code>), and its key is not already in the ledger.</li><li><strong>Insert</strong> the survivors; duplicates and refuted candidates cancel.</li><li><strong>Ship</strong> — <code>npm run next</code>: discover → gate → seal → deploy. Waves ride in <strong>octaves of 8</strong>, so the ledger grows <code>N × 8</code>; a massive wave keeps the octave by cancelling the remainder.</li></ol><h2 id="verify-—-the-regression-guard-—-npm-run-verify" tabindex="-1">Verify — the regression guard — <code>npm run verify</code> <a class="header-anchor" href="#verify-—-the-regression-guard-—-npm-run-verify" aria-label="Permalink to “Verify — the regression guard — npm run verify”">​</a></h2><p>The release trusts the saved ledger; this <strong>re-runs every recorded theorem&#39;s test</strong>, re-gates every name, and checks the chain-of-custody and duplicate keys. A silent regression (a test that no longer computes true, a name that drains) is caught here. It scales — the whole ledger re-verifies in seconds.</p><h2 id="the-gate-—-hold-the-honest-floor" tabindex="-1">The gate — hold the honest floor <a class="header-anchor" href="#the-gate-—-hold-the-honest-floor" aria-label="Permalink to “The gate — hold the honest floor”">​</a></h2><p>Every name and message must pass <code>computes()</code>: no unbounded over-reach (RED / OVERREACH, seven languages, negation-aware so a bounded refusal passes). The gate is a <strong>tripwire, not an oracle</strong> — when a class of over-claim leaks, strengthen it by trial: gather the leaks, edit the patterns, re-trial until <strong>the leaks drain ∧ honest statements pass ∧ no existing ledger name over-drains.</strong></p><h2 id="the-seal-—-ship-—-npm-run-next" tabindex="-1">The seal — ship — <code>npm run next</code> <a class="header-anchor" href="#the-seal-—-ship-—-npm-run-next" aria-label="Permalink to “The seal — ship — npm run next”">​</a></h2><p><code>discover → release</code> (tsc, gaps, the gates, forensics, seal, <code>docs:build</code> → <code>sw-integrity</code> manifest, deploy). The <strong>content-address is the true latest</strong>; the version is a single-digit odometer, and LTS versions are the Fibonacci minors <code>{1,2,3,5,8}</code>.</p><h2 id="the-proxy-—-the-pwa-over-assumed-insecure-transport" tabindex="-1">The proxy — the PWA over assumed-insecure transport <a class="header-anchor" href="#the-proxy-—-the-pwa-over-assumed-insecure-transport" aria-label="Permalink to “The proxy — the PWA over assumed-insecure transport”">​</a></h2><p>The service worker proxies all traffic, verifies every same-origin asset against the build-time SHA-256 manifest (pure-JS, no native crypto), refuses a tampered response, and <strong>signs each verified asset into a chained content-address receipt</strong> — a tamper-evident, auditable traffic stream. Integrity, not confidentiality.</p><p>A content-address proves <strong>integrity, not truth</strong>.</p>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};